import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function QueueExample() {
    var items = React.useState([1, 2, 3, 4, 5]), serial = React.useRef(5), position = React.useState('bottom-center'), order = React.useState('oldest-first'), toolbar = React.useRef(null), trigger = React.useRef(null);
    React.useLayoutEffect(function () { trigger.current = toolbar.current.querySelector('button'); }, []);
    function dismiss(id) { items[1](function (list) { return list.filter(function (item) { return item !== id; }); }); }
    return <div className={"demo-stack"}>
    <div className={'toolbar'} ref={toolbar}>
    <S.DsButton tone={'secondary'} disabled={items[0].length >= 8} onClick={function () { serial.current++; var id = serial.current; items[1](function (list) { return list.concat(id); }); }}>
    {'Добавить уведомление'}
    </S.DsButton>
    <S.DsButton tone={'subtle'} onClick={function () { position[1](position[0] === 'bottom-center' ? 'bottom-right' : 'bottom-center'); }}>
    {position[0] === 'bottom-center' ? 'Разместить справа' : 'Разместить по центру'}
    </S.DsButton>
    <S.DsButton tone={'subtle'} onClick={function () { order[1](order[0] === 'oldest-first' ? 'newest-first' : 'oldest-first'); }}>
    {order[0] === 'oldest-first' ? 'Новые сверху' : 'Старые сверху'}
    </S.DsButton>
    </div>
    <p className={'description'}>
    {'Видно: ' + Math.min(3, items[0].length) + '. Ожидают: ' + Math.max(0, items[0].length - 3) + '. Закройте сообщение — появится следующее. В примере можно добавить до восьми.'}
    </p>
    <p className={'description'}>
    {'Перейдите к кнопке закрытия клавишей Tab и нажмите Enter. Фокус перейдёт к соседнему сообщению, после последнего — к кнопке добавления.'}
    </p>
    <div className={'demo'} style={{ minHeight: items[0].length ? Math.min(items[0].length, 3) * 112 + 56 : 0 }}>
    <S.DsToastStack position={position[0]} order={order[0]} label={'Результаты операций'} returnFocusRef={trigger}>
    {items[0].map(function (id) {
            return <S.DsToast key={id} tone={id % 2 ? 'success' : 'info'} announcement={id <= 3 ? 'off' : 'polite'} closeLabel={'Закрыть уведомление ' + id} onClose={function () { dismiss(id); }}>
    {id === 5 ? 'Экспорт 5 готов. Отчёт включает объекты всех подразделений и данные за последний месяц. Файл доступен в разделе отчётов.' : id % 2 ? 'Изменение ' + id + ' сохранено.' : 'Экспорт ' + id + ' готов к скачиванию.'}
    </S.DsToast>;
        })}
    </S.DsToastStack>
    </div>
    {!items[0].length ? <p className={'description'}>
    {'Нет уведомлений. Добавьте новое, чтобы снова увидеть стек.'}
    </p> : null}
    </div>;
}
function App() {
    return <div className="dstoaststack-example">
    <style>{exampleStyles}</style>
    <QueueExample />
    </div>;
}

const exampleStyles = ".dstoaststack-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dstoaststack-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dstoaststack-example p{margin:0}\n.dstoaststack-example .toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:center}\n.dstoaststack-example .description{margin:12px 0 0;color:var(--ds-fg-muted)}\n.dstoaststack-example .demo{position:relative;transform:translateZ(0);overflow-wrap:anywhere}";

export { App as Example };

